	@Inject protected InterruptManager interruptManager;

	private boolean checkInMainRegion(){
		int[] currentMapRegions = client.getMapRegions();
		return currentMapRegions != null && Arrays.stream(currentMapRegions).anyMatch(x -> x == MINIGAME_MAIN_REGION);
	}

	@Subscribe
	public void onChatMessage(ChatMessage chatMessage)
	{
		if(!checkInMainRegion()) return;
		if(chatMessage.getType() != ChatMessageType.SPAM && chatMessage.getType() != ChatMessageType.GAMEMESSAGE) return;

		String msg = chatMessage.getMessage();
		Matcher rewardPointMatcher = REWARD_POINT_PATTERN.matcher(msg);

		if(msg.contains("You found some loot:")){
			currentElementalRewardPoints--;
			currentCatalyticRewardPoints--;
		}
		else if(msg.contains("The Great Guardian was defeated!")){
			interruptManager.interrupt("Guardian of the Rift game concluded");
		}
		else if(rewardPointMatcher.find()) {
			interruptManager.interrupt("Guardian of the Rift game concluded");
			currentElementalRewardPoints = Integer.parseInt(rewardPointMatcher.group(1).replaceAll(",", ""));
			currentCatalyticRewardPoints = Integer.parseInt(rewardPointMatcher.group(2).replaceAll(",", ""));
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked evt)
	{
		if(!checkInMainRegion()) return;

		if (evt.getId() == REWARD_GUARDIAN_ID && evt.getMenuOption().toLowerCase().equals("search")){
			triggeringRewardSearch = true;
		}

		if(evt.getId() == WORKBENCH_ID && evt.getMenuOption().toLowerCase().equals("work-at")){			
			triggeringEssenceCrafting = true;
			ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
			numberOfGuardianEssencesToMake = inventory == null ? 0 : Math.min(inventory.count(GUARDIAN_FRAGMENTS_ITEM_ID), this.inventoryManager.getFreeSpaces());
		}
	}

	@Subscribe
	public void onGameTick(GameTick evt)
	{
		if(!checkInMainRegion()) return;

		Widget dialog = client.getWidget(DIALOG_WIDGET_GROUP, DIALOG_WIDGET_MESSAGE);
		if (dialog != null){			
		String dialogText = dialog.getText();
		final Matcher checkMatcher = CHECK_POINT_PATTERN.matcher(dialogText);
		if (checkMatcher.find(0))
		{
			currentCatalyticRewardPoints = Integer.parseInt(checkMatcher.group(1));
			currentElementalRewardPoints = Integer.parseInt(checkMatcher.group(2));
			}
		}

		Player local = this.client.getLocalPlayer();
		if (local == null || local.getAnimation() == -1) return;

		log.debug (local.getAnimation() + " local animation");

		if (triggeringEssenceCrafting && local.getAnimation() == CRAFTING_ANIMATION_ID){
			triggeringEssenceCrafting = false;

			if (numberOfGuardianEssencesToMake == 0) return;

			this.actionManager.setAction(Action.GUARDIAN_OF_THE_RIFT_CRAFTING, numberOfGuardianEssencesToMake, ItemID.GUARDIAN_ESSENCE);	
		}
		else if (triggeringRewardSearch && local.getAnimation() == REWARD_SEARCHING_ANIMATION_ID){
			triggeringRewardSearch = false;

			int numberOfRewards = Math.min(currentElementalRewardPoints, currentCatalyticRewardPoints);

			if (numberOfRewards == 0) return;

			this.actionManager.setAction(Action.GUARDIAN_OF_THE_RIFT_REWARD_POOL, numberOfRewards, -1);
		}

	}
}

package com.github.calebwhiting.runelite.plugins.actionprogress.detect;

import com.github.calebwhiting.runelite.data.Magic;
import com.github.calebwhiting.runelite.plugins.actionprogress.Action;
import com.github.calebwhiting.runelite.plugins.actionprogress.ActionProgressConfig;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.Skill;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;

@Singleton
public class BakePieSpellDetector extends ActionDetector
{

	@Inject private ActionProgressConfig config;

	@Inject private Client client;

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked evt)
	{
		if (!this.config.magicBakePie()) {
			return;
		}
		if (evt.getMenuAction() != MenuAction.CC_OP) {
			return;
		}
		ItemContainer inventory = this.client.getItemContainer(InventoryID.INV);
		if (inventory == null) {
			return;
		}
		int cookingLevel = this.client.getBoostedSkillLevel(Skill.COOKING);

		// There is not a space in the middle of Bake Pie, it is a '\u00A0' afaik
		// We are matching "Bake[standard ASCII plus the whitespace codepoints]Pie"
		if(!evt.getMenuTarget().matches(".*Bake\\p{Z}Pie.*")) {
			return;
		}
		int amount = 0;
		int itemId = 0;
		for (Magic.BakePieSpell bakePieSpell : Magic.BakePieSpell.values()) {
			Magic.Spell spell = bakePieSpell.getSpell();
			Widget widget = this.client.getWidget(spell.getWidgetId());
			if (widget != null && widget.getBorderType() == 0) {
				int curItemId = bakePieSpell.getPieId();
				// filter out pies that player does not have the level to cook
				if (bakePieSpell.getLevel() > cookingLevel) {
					continue;
				}
				if (inventory.count(curItemId) <= 0) {
					continue;
				}
				// We are storing the last itemID and appending amount because
				// Bake Pie will cook all pies in the inv that the user has the level for.
				itemId = curItemId;
				amount += Math.min(inventory.count(itemId), spell.getAvailableCasts(this.client));
			}
		}
		// Check if any item was found
		if (itemId > 0) {
			this.actionManager.setAction(Action.MAGIC_BAKE_PIE, amount, itemId);
		}
	}

}

package com.github.calebwhiting.runelite.plugins.actionprogress.detect;

import com.github.calebwhiting.runelite.plugins.actionprogress.Action;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.ItemContainer;
import net.runelite.api.ItemID;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;

import java.awt.event.KeyEvent;
import java.util.HashMap;

@Singleton
@Slf4j
public class SmithingDetector extends ActionDetector implements KeyListener
{

	@Inject private Client client;

	@Inject private ClientThread clientThread;

	@Inject private KeyManager keyManager;

	private static final int VAR_AVAILABLE_MATERIALS = 2224;

	private static final int VAR_SMITHING_INTERFACE = 989;

	private static final int VAR_SELECTED_SMITHING_INDEX = 13895;

	private static final int SCRIPT_SMITHING_INIT = 431;

	private static final int ENUM_SMITHING_WIDGET_INDEX = 1101;

	private static final int ENUM_SMITHING_ITEM_BAR = 845;

	private int smithingItemid;

	private int numberOfBarsForSelectedItem;

	private boolean waitingForSmithingSelection = false;

	private boolean pendingSmithingClickStart = false;

	private HashMap<Integer, Integer> indexToItemId = new HashMap<Integer,Integer>();

	@Override
	public void keyTyped(KeyEvent event)
	{

	}

	@Override
	public void keyReleased(KeyEvent event)
	{

	}

	@Override
	public void keyPressed(KeyEvent event)
	{
		if (waitingForSmithingSelection && event.getKeyCode() == KeyEvent.VK_SPACE)
		{
			clientThread.invokeLater(() -> {
				int availableBars = this.client.getVarpValue(VAR_AVAILABLE_MATERIALS);
				if(numberOfBarsForSelectedItem == 0)
				{
					return;
				}

				if(isWearingSmithOutfit()){
					this.actionManager.setAction(Action.SMITHING_WITH_SMITH_OUTFIT, (availableBars / numberOfBarsForSelectedItem), smithingItemid);
				}
				else {
					this.actionManager.setAction(Action.SMITHING, (availableBars / numberOfBarsForSelectedItem), smithingItemid);
				}
			});
		}
	}

	@Override
	public void setup()
	{
		keyManager.registerKeyListener(this);
	}

	@Override
	public void shutDown()
	{
		keyManager.unregisterKeyListener(this);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged evt)
	{
		if (evt.getVarbitId() == VAR_SELECTED_SMITHING_INDEX) {			
			int index = evt.getValue();
			if(indexToItemId.containsKey(index)){
				smithingItemid = indexToItemId.get(index);
				numberOfBarsForSelectedItem = client.getEnum(ENUM_SMITHING_ITEM_BAR).getIntValue(smithingItemid);
			}			
		}
	}

	@Subscribe
	public void onVarClientIntChanged(VarClientIntChanged varClientIntChanged)
	{
		if (varClientIntChanged.getIndex() == VAR_SMITHING_INTERFACE)
		{
			boolean wasWaitingForSmithingSelection = waitingForSmithingSelection;
			waitingForSmithingSelection = !waitingForSmithingSelection;

			if (!waitingForSmithingSelection) {
				if (wasWaitingForSmithingSelection && pendingSmithingClickStart) {
					pendingSmithingClickStart = false;
					clientThread.invokeLater(() -> {
						if (smithingItemid <= 0 || numberOfBarsForSelectedItem <= 0) {
							return;
						}

						startSmithingAction(numberOfBarsForSelectedItem, smithingItemid);
					});
				}
			}
			else {
				pendingSmithingClickStart = false;
			}
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired evt)
	{
		if (evt.getScriptId() == SCRIPT_SMITHING_INIT){
			final int[] intStack = client.getIntStack();
			final int intStackSize = client.getIntStackSize();
			final int widgetId = intStack[intStackSize - 4];			
			final int itemId = intStack[intStackSize - 3];

			int index = client.getEnum(ENUM_SMITHING_WIDGET_INDEX).getIntValue(widgetId);
			indexToItemId.put(index, itemId);

			int var_index = this.client.getVarbitValue(VAR_SELECTED_SMITHING_INDEX);

			try {
				smithingItemid = indexToItemId.get(var_index);
				numberOfBarsForSelectedItem = client.getEnum(ENUM_SMITHING_ITEM_BAR).getIntValue(smithingItemid);
			}catch (NullPointerException e){
				log.debug("Item not found in indexToItemId map");
			}

		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked evt)
	{
		if (!waitingForSmithingSelection || !isSmithingProductClick(evt)) {
			return;
		}

		pendingSmithingClickStart = true;
	}

	private void startSmithingAction(int barsPerItem, int productId)
	{
		if (barsPerItem <= 0) {
			return;
		}

		int availableBars = this.client.getVarpValue(VAR_AVAILABLE_MATERIALS);
		if(isWearingSmithOutfit()){
			this.actionManager.setAction(Action.SMITHING_WITH_SMITH_OUTFIT, (availableBars / barsPerItem), productId);
		}
		else {
			this.actionManager.setAction(Action.SMITHING, (availableBars / barsPerItem), productId);
		}
	}

	private boolean isSmithingProductClick(MenuOptionClicked evt)
	{
		Widget current = evt.getWidget();
		if (current == null && evt.getParam1() != -1) {
			current = this.client.getWidget(evt.getParam1());
		}

		while (current != null) {
			if (current.getParentId() == ComponentID.SMITHING_INVENTORY_ITEM_CONTAINER) {
				return true;
			}
			if ((current.getId() >>> 16) == InterfaceID.SMITHING) {
				return true;
			}

			int parentId = current.getParentId();
			if (parentId == -1 || parentId == current.getId()) {
				break;
			}

			Widget parent = current.getParent();
			current = parent != null ? parent : client.getWidget(parentId);
		}

		return evt.getParam1() != -1 && (evt.getParam1() >>> 16) == InterfaceID.SMITHING;
	}

	private boolean isWearingSmithOutfit(){
		ItemContainer gear = this.client.getItemContainer(InventoryID.EQUIPMENT);
		if (gear == null) {
			return false;
		}
        return gear.contains(ItemID.SMITHS_TUNIC) &&
                gear.contains(ItemID.SMITHS_TROUSERS) &&
                gear.contains(ItemID.SMITHS_BOOTS) &&
                (gear.contains(ItemID.SMITHS_GLOVES) || gear.contains(ItemID.SMITHS_GLOVES_I));
    }

}

package com.github.calebwhiting.runelite.plugins.actionprogress.detect;

import com.github.calebwhiting.runelite.api.InventoryManager;
import com.github.calebwhiting.runelite.api.event.LocalAnimationChanged;
import com.github.calebwhiting.runelite.data.Woodcutting;
import com.github.calebwhiting.runelite.plugins.actionprogress.Action;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import net.runelite.api.Item;
import net.runelite.api.ObjectID;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.eventbus.Subscribe;

import java.util.Arrays;

/**
 * Detects the direct Forester's Campfire flow used when the inventory contains only one log type.
 * The multi-log flow still opens Make-X and is handled by {@link ChatboxDetector}.
 */
@Singleton
public class CampfireDetector extends ActionDetector
{
	private static final String TEND_TO_OPTION = "Tend-to";

	private static final int[] CAMPFIRE_ANIMATIONS = {
			AnimationID.FORESTRY_CAMPFIRE_BURNING_GENERIC,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ACHEY_TREE_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ARCTIC_PINE_LOG,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_BLISTERWOOD_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAGIC_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAHOGANY_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAPLE_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_OAK_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_REDWOOD_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_TEAK_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_WILLOW_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_YEW_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_JATOBA_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_CAMPHOR_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_IRONWOOD_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ROSEWOOD_LOGS,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_GENERIC_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ACHEY_TREE_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ARCTIC_PINE_LOG_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_BLISTERWOOD_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAGIC_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAHOGANY_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_MAPLE_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_OAK_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_REDWOOD_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_TEAK_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_WILLOW_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_YEW_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_JATOBA_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_CAMPHOR_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_IRONWOOD_LOGS_NOLOOP,
			AnimationID.FORESTRY_CAMPFIRE_BURNING_ROSEWOOD_LOGS_NOLOOP
	};

	@Inject InventoryManager inventoryManager;

	private int pendingLogId = -1;
	private int pendingLogCount;

	@Override
	public void setup()
	{
		this.clearPendingAction();
	}

	@Override
	public void shutDown()
	{
		this.clearPendingAction();
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked evt)
	{
		this.clearPendingAction();
		if (!TEND_TO_OPTION.equalsIgnoreCase(evt.getMenuOption()) ||
			!isForestersCampfire(evt.getId())) {
			return;
		}

		for (int logId : Woodcutting.CAMPFIRE_LOGS) {
			int count = this.inventoryManager.getItems()
					.filter(item -> item.getId() == logId)
					.mapToInt(Item::getQuantity)
					.sum();
			if (count == 0) {
				continue;
			}
			if (this.pendingLogId != -1) {
				this.clearPendingAction();
				return;
			}
			this.pendingLogId = logId;
			this.pendingLogCount = count;
		}
	}

	@Subscribe
	public void onLocalAnimationChanged(LocalAnimationChanged evt)
	{
		if (this.pendingLogId == -1 || !isCampfireAnimation(evt.getLocalPlayer().getAnimation())) {
			return;
		}

		int logId = this.pendingLogId;
		int logCount = this.pendingLogCount;
		this.clearPendingAction();
		if (this.actionManager.getCurrentAction() != Action.FIREMAKING_CAMPFIRE) {
			this.actionManager.setAction(Action.FIREMAKING_CAMPFIRE, logCount, logId);
		}
	}

	private void clearPendingAction()
	{
		this.pendingLogId = -1;
		this.pendingLogCount = 0;
	}

	private static boolean isCampfireAnimation(int animationId)
	{
		return Arrays.stream(CAMPFIRE_ANIMATIONS).anyMatch(id -> id == animationId);
	}

	private static boolean isForestersCampfire(int objectId)
	{
		return objectId == ObjectID.FORESTERS_CAMPFIRE ||
				objectId == ObjectID.FORESTERS_CAMPFIRE_49928 ||
				objectId == ObjectID.FORESTERS_CAMPFIRE_49929 ||
				objectId == ObjectID.FORESTERS_CAMPFIRE_49930 ||
				objectId == ObjectID.FORESTERS_CAMPFIRE_49931 ||
				objectId == ObjectID.FORESTERS_CAMPFIRE_49932;
	}
}

package com.github.calebwhiting.runelite.plugins.actionprogress.detect;

import com.github.calebwhiting.runelite.plugins.actionprogress.Action;
import com.google.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.annotations.Varbit;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.eventbus.Subscribe;

public class TemporossRewardPoolDetector extends ActionDetector
{

	@Varbit private static final int VAR_TEMPOROSS_PERMITS = VarbitID.TEMPOROSS_REWARDPERMITS;

	@Inject private Client client;

	private int previousPermits = -1;

	@Subscribe
	public void onGameTick(GameTick evt)
	{
		int permits = this.client.getVarbitValue(VAR_TEMPOROSS_PERMITS);
		if (permits < this.previousPermits) {
			int permitsUsed = previousPermits - permits;
			boolean bigSearch = permitsUsed > 1;
			int searches = bigSearch ? (previousPermits + 4) / 5 : previousPermits;
			if (this.actionManager.getCurrentAction() != Action.TEMPOROSS_REWARD_POOL) {
				this.actionManager.setAction(Action.TEMPOROSS_REWARD_POOL, searches, -1);
			}
		}
		this.previousPermits = permits;
	}

}

package com.github.calebwhiting.runelite.plugins.actionprogress.detect;

import com.github.calebwhiting.runelite.data.Magic;
